import socket,json,urllib.request
r={}
opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
r['ollama_version']=json.load(opener.open('http://127.0.0.1:11434/api/version',timeout=3))
for key,address in [('other_loopback',('127.0.0.1',1)),('external',('1.1.1.1',443))]:
    try:
        with socket.create_connection(address,timeout=1): pass
        r[key]={'status':'ALLOWED'}
    except OSError as e:
        r[key]={'errno':e.errno,'error':str(e)}
print(json.dumps(r))
